#' Create html table with the results of the evaluation
#'
#' @param table \code{dataframe} generated by evaluate function
#'
#' @return \code{html} table
#'
#' @import kableExtra
#' @export

create_html <- function(table) {

  # Caso INE
  if (sum(class(table) %in% "ine.eval") > 0) {
    table %>%
      dplyr::mutate_if(is.numeric, ~round(.x, 2)) %>%
      dplyr::mutate(
        label = kableExtra::cell_spec(.data$label, background = dplyr::case_when(
          .data$label == "reliable" ~ "green",
          .data$label == "weakly reliable" ~ "yellow",
          .data$label == "non-reliable" ~ "red",
          TRUE ~ "white" # <--- ESTA LINEA EVITA EL ERROR
        ), color = "black")) %>%
      dplyr::mutate(
        n = kableExtra::cell_spec(.data$n, color = dplyr::case_when(
          .data$n < 60 ~ "red",
          .data$n >= 60 ~ "black",
          TRUE ~ "black"
        )),
        df = kableExtra::cell_spec(.data$df, color = dplyr::case_when(
          .data$df < 9 ~ "red",
          .data$df >= 9 ~ "black",
          TRUE ~ "black"
        ))) %>%
      kableExtra::kable(format.args = list(decimal.mark = ',', big.mark = "."),
                        format = "html", escape = FALSE, align = "c",
                        table.attr = "style = \"color: black;\"") %>%
      kableExtra::kable_styling("striped", full_width = FALSE, html_font = "arial") %>%
      kableExtra::kable_paper("hover") %>%
      kableExtra::row_spec(0, bold = TRUE, color = "black")

    # Caso CEPAL 2020
  } else if (sum(class(table) %in% "cepal2020.eval") > 0) {
    table %>%
      dplyr::mutate_if(is.numeric, ~round(.x, 2)) %>%
      dplyr::mutate(
        label = kableExtra::cell_spec(.data$label, background = dplyr::case_when(
          .data$label == "publish" ~ "green",
          .data$label == "review" ~ "yellow",
          .data$label == "supress" ~ "red",
          TRUE ~ "white" # <--- ESTA LINEA EVITA EL ERROR
        ), color = "black")) %>%
      dplyr::mutate(
        n = kableExtra::cell_spec(.data$n, color = dplyr::case_when(
          .data$n < 60 ~ "red",
          .data$n >= 60 ~ "black",
          TRUE ~ "black"
        )),
        df = kableExtra::cell_spec(.data$df, color = dplyr::case_when(
          .data$df < 9 ~ "red",
          .data$df >= 9 ~ "black",
          TRUE ~ "black"
        ))) %>%
      kableExtra::kable(format.args = list(decimal.mark = ',', big.mark = "."),
                        format = "html", escape = FALSE, align = "c",
                        table.attr = "style = \"color: black;\"") %>%
      kableExtra::kable_styling("striped", full_width = FALSE, html_font = "arial") %>%
      kableExtra::kable_paper("hover") %>%
      kableExtra::row_spec(0, bold = TRUE, color = "black")

    # Caso CEPAL 2023
  } else if (sum(class(table) %in% "cepal2023.eval") > 0) {
    table %>%
      dplyr::mutate_if(is.numeric, ~round(.x, 2)) %>%
      dplyr::mutate(
        label = kableExtra::cell_spec(.data$label, background = dplyr::case_when(
          .data$label == "reliable" ~ "green",
          .data$label == "weakly-reliable" ~ "yellow",
          .data$label == "non-reliable" ~ "red",
          TRUE ~ "white" # <--- ESTA LINEA EVITA EL ERROR
        ), color = "black")) %>%
      dplyr::mutate(
        n = kableExtra::cell_spec(.data$n, color = dplyr::case_when(
          .data$n < 60 ~ "red",
          .data$n >= 60 ~ "black",
          TRUE ~ "black"
        )),
        df = kableExtra::cell_spec(.data$df, color = dplyr::case_when(
          .data$df < 9 ~ "red",
          .data$df >= 9 ~ "black",
          TRUE ~ "black"
        ))) %>%
      kableExtra::kable(format.args = list(decimal.mark = ',', big.mark = "."),
                        format = "html", escape = FALSE, align = "c",
                        table.attr = "style = \"color: black;\"") %>%
      kableExtra::kable_styling("striped", full_width = FALSE, html_font = "arial") %>%
      kableExtra::kable_paper("hover") %>%
      kableExtra::row_spec(0, bold = TRUE, color = "black")

    # Caso economicas
    #AAAAAA
    #AAAAAA
  } else if (sum(class(table) %in% "economicas.eval") > 0) {
    table %>%
      dplyr::mutate_if(is.numeric, ~round(.x, 2)) %>%
      dplyr::mutate(
        label = kableExtra::cell_spec(.data$label, background = dplyr::case_when(
          .data$label == "reliable" ~ "green",
          .data$label == "weakly-reliable" ~ "yellow",
          .data$label == "non-reliable" ~ "red",
          TRUE ~ "white"  # ESTO ES PARA LOS NA, no estoy segunro si esta bien
        ), color = "black")) %>%
      dplyr::mutate(
        n = kableExtra::cell_spec(.data$n, color = dplyr::case_when(
          .data$n < 60 ~ "red",
          .data$n >= 60 ~ "black",
          TRUE ~ "black"
        )),
        df = kableExtra::cell_spec(.data$df, color = dplyr::case_when(
          .data$df < 9 ~ "red",
          .data$df >= 9 ~ "black",
          TRUE ~ "black"
        ))) %>%
      kableExtra::kable(format.args = list(decimal.mark = ',', big.mark = "."),
                        format = "html", escape = FALSE, align = "c",
                        table.attr = "style = \"color: black;\"") %>%
      kableExtra::kable_styling("striped", full_width = FALSE, html_font = "arial") %>%
      kableExtra::kable_paper("hover") %>%
      kableExtra::row_spec(0, bold = TRUE, color = "black")
  }
}


